function documentDeepInfo(code, record) { const pending = /Chờ|Cần/.test(record.status); const signed = record.status === "Chờ ký số" ? "Chờ đối tác ký số" : "Chữ ký số hợp lệ"; const type = record.group === "Pháp lý" ? "Tài liệu pháp nhân" : record.group === "Chứng nhận" ? "Chứng nhận tiêu chuẩn" : record.group === "Hợp đồng" ? "Hồ sơ thương mại" : record.group === "Kiểm nghiệm" ? "Kết quả kiểm soát chất lượng" : "Hồ sơ thành viên"; const relationships = record.group === "Hợp đồng" ? [["Đơn tiêu thụ",record.linked,"Căn cứ thực hiện","Đang xử lý"],["HTX", "HTX-001 · Tân Thuận","Bên cung ứng","Đang hoạt động"],["Lô hàng","SR-2408-16","Nguồn phân bổ","Đã đối soát"]] : record.group === "Kiểm nghiệm" ? [["Lô hàng",record.linked,"Đối tượng kiểm nghiệm","Đạt"],["Mùa vụ","MV-TD26-01","Nguồn vùng trồng","Đã đối soát"],["Thửa đất","TD-042, TD-057","Truy xuất nguồn gốc","Đủ dữ liệu"]] : record.group === "Thành viên" ? [["Thành viên",record.linked,"Hồ sơ chủ thể",pending ? "Cần bổ sung" : "Đã xác thực"],["HTX","HTX-001 · Tân Thuận","Thành viên thuộc","Đang hoạt động"],["Thửa đất","TD-042, TD-057","Vùng liên kết","Đã số hóa"]] : [[record.group === "Chứng nhận" ? "Vùng sản xuất" : "Hợp tác xã",record.linked,"Đối tượng áp dụng","Đang hoạt động"],["Hồ sơ liên quan",code === "HS-PL-022" ? "HS-QT-014 · Điều lệ HTX" : "HS-PL-022 · Pháp lý HTX","Căn cứ tuân thủ","Hiệu lực"],["Người phụ trách",record.owner,"Quản lý hồ sơ","Đang hoạt động"]]; return { mime:"PDF/A-2b", integrity: pending ? "Đang chờ kiểm tra lại" : "Tệp nguyên vẹn, đã kiểm tra", hash:"SHA-256: 8fc1…a92d · kiểm tra 20/08/2026", signature:signed, signer:record.status === "Chờ ký số" ? "Chờ đại diện đối tác xác thực" : "VNPT-CA · thời hạn đến 18/03/2029", retention:record.group === "Pháp lý" ? "Lưu vĩnh viễn" : record.group === "Hợp đồng" ? "10 năm sau khi thanh lý" : "05 năm kể từ ngày hết hiệu lực", retentionNote:"Theo quy chế lưu trữ hồ sơ điện tử của HTX và yêu cầu truy xuất nội bộ.", metadata:[["Mã định danh",code],["Loại tài liệu",type],["Nhóm hồ sơ",record.group],["Đơn vị tạo",record.source],["Ngôn ngữ","Tiếng Việt"],["Định dạng / dung lượng","PDF/A-2b · " + record.file.split(" · ").at(-1)],["Mức độ truy cập",record.group === "Thành viên" ? "Nội bộ hạn chế" : "Nội bộ HTX"],["Tình trạng chỉ mục","Đã lập chỉ mục toàn văn"],["Mã phân loại","HS/2026/" + record.group.toUpperCase().slice(0,3)]], approvals:[["Người lập",record.owner,record.issued,"Đã hoàn tất"],["Kiểm tra nghiệp vụ",record.group === "Tài chính" ? "Kế toán trưởng" : "Nguyễn Minh Tâm",pending ? "Chờ xử lý" : "20/08/2026 · 10:15",pending ? "Chờ xử lý" : "Đã phê duyệt"],["Phê duyệt cuối",record.status === "Chờ ký số" ? "Đại diện đối tác" : "Bà Lê Thị Thanh Vân",record.status === "Chờ ký số" ? "Chờ ký số" : "20/08/2026 · 11:00",record.status === "Chờ ký số" ? "Chờ ký số" : "Đã phê duyệt"]], access:[["Quản trị HTX","Toàn quyền"],["Chủ hồ sơ / đơn vị phụ trách","Tạo, cập nhật, xem"],["Kế toán và điều phối liên quan","Xem, tải bản sao"],["Thành viên / đối tác","Chỉ xem khi được chia sẻ"]], relationships, basis:record.group === "Hợp đồng" ? "Hợp đồng thương mại và đơn tiêu thụ phát sinh." : record.group === "Kiểm nghiệm" ? "Phiếu lấy mẫu và yêu cầu xuất kho lô hàng." : record.group === "Chứng nhận" ? "Kế hoạch đánh giá vùng trồng và tiêu chuẩn VietGAP." : record.group === "Thành viên" ? "Hồ sơ đăng ký thành viên và dữ liệu định danh." : "Hồ sơ đăng ký và điều lệ tổ chức hợp tác xã.", audit:[["20/08 · 10:30","Hệ thống kiểm tra liên kết bản ghi và toàn vẹn tệp"],["20/08 · 10:31","Cập nhật chỉ mục tìm kiếm nội bộ"],["20/08 · 10:32","Ghi nhận truy cập gần nhất bởi Quản trị HTX"]] }; }

function LandGisModule({ parcel, onSelectParcel, onNotice }) {
  const [records, setRecords] = useState([]); const [selectedParcel, setSelectedParcel] = useState(null); const [profile, setProfile] = useState(null); const [drawerOpen, setDrawerOpen] = useState(false); const [creating, setCreating] = useState(false); const [showQr, setShowQr] = useState(false); const [error, setError] = useState("");
  const load = () => apiGet("/api/parcels?cooperativeCode=HTX-001").then(({ data }) => { const mapped = data.map(parcelMap); setRecords(mapped); if (!selectedParcel && mapped.length) select(mapped.find((item) => item.id === parcel?.id) || mapped[0]); }).catch((reason) => setError(reason.message));
  useEffect(() => { load(); }, []);
  const select = (next) => { setSelectedParcel(next); onSelectParcel(next); apiGet(`/api/parcels/${next.id}/profile`).then(({ data }) => setProfile(parcelProfileView(data))).catch((reason) => setError(reason.message)); };
  const fields = [{ name:"code", label:"Mã thửa đất", required:true },{ name:"memberCode", label:"Mã thành viên", placeholder:"VD: TV-102", required:true },{ name:"areaHa", label:"Diện tích (ha)", type:"number", placeholder:"0,0", required:true },{ name:"crop", label:"Cây trồng chính", required:true },{ name:"zoneCode", label:"Mã vùng trồng", required:true },{ name:"coordinates", label:"Tọa độ (vĩ độ, kinh độ)", placeholder:"10.452478, 105.682255", wide:true, required:true }];
  const statistics = useMemo(() => ({ total:records.reduce((sum, item) => sum + item.areaHa, 0), standards:records.filter((item) => item.standard === "VietGAP").reduce((sum, item) => sum + item.areaHa, 0), conversion:records.filter((item) => item.standard === "conversion").reduce((sum, item) => sum + item.areaHa, 0) }), [records]);
  if (!selectedParcel) return <section className="module-screen"><ModuleHero icon={IconMap2} eyebrow="Quản lý đất đai" title="Đất đai & GIS" description="Đang tải dữ liệu thửa đất từ MongoDB." actionLabel="Thêm thửa đất" onAction={() => setCreating(true)} />{error && <p className="data-source-error">Không thể tải dữ liệu MongoDB: {error}</p>}</section>;
  return <section className="module-screen land-screen"><ModuleHero icon={IconMap2} eyebrow="Quản lý đất đai" title="Đất đai & GIS" description="Theo dõi thửa đất, ranh giới, tiêu chuẩn, vùng trồng và nhật ký hiện trường trên bản đồ." actionLabel="Thêm thửa đất" onAction={() => setCreating(true)} />{error && <p className="data-source-error">Không thể tải dữ liệu MongoDB: {error}</p>}<div className="gis-workspace panel"><div className="full-map"><MapWidget selectedParcel={selectedParcel} parcels={records} onSelect={select} /><div className="map-actions"><button className="outline-btn" onClick={() => setCreating(true)}>Thêm thửa đất</button><button className="primary-btn" onClick={() => setShowQr(true)}><IconQrcode size={16} />Tạo mã truy xuất</button></div><div className="map-count"><IconMap2 size={17} /><b>{records.length} thửa đất</b><span>{statistics.total} ha đã số hóa</span></div></div><aside className="gis-detail"><span className="small-label">THỬA ĐẤT ĐANG CHỌN</span><h3>{selectedParcel.id}</h3><Status value={profile?.status || "Đang tải"} /><Detail label="Chủ sử dụng" value={selectedParcel.name} /><Detail label="Cây trồng" value={selectedParcel.crop} /><Detail label="Diện tích" value={selectedParcel.area} /><Detail label="Mã vùng trồng" value={profile?.zoneCode || selectedParcel.zoneCode} /><Detail label="Nhật ký kỳ này" value={`${profile?.logs.length || 0} bản ghi`} /><button className="outline-btn wide" onClick={() => setDrawerOpen(true)}><IconFileText size={17} />Mở hồ sơ thửa đất</button></aside></div><div className="gis-summary"><Summary icon={IconCircleCheck} value={`${statistics.standards} ha`} label="Đạt VietGAP" /><Summary icon={IconCalendarEvent} value={`${records.filter((item) => item.standard !== "VietGAP").length} thửa`} label="Cần theo dõi" /><Summary icon={IconPlant2} value={`${statistics.conversion} ha`} label="Đang chuyển đổi" /></div><section className="land-register panel"><PanelHead title="Sổ bộ thửa đất" subtitle="Dữ liệu thửa, vùng trồng và tiêu chuẩn được đọc từ MongoDB" action="Mở hồ sơ thửa đang chọn" onClick={() => setDrawerOpen(true)} /><div className="table-scroll"><table><thead><tr>{["Mã thửa","Chủ sử dụng","Cây trồng","Diện tích","Mã vùng","Trạng thái"].map((item) => <th key={item}>{item}</th>)}</tr></thead><tbody>{records.map((item) => <tr key={item.id} onClick={() => { select(item); setDrawerOpen(true); }}><td>{item.id}</td><td>{item.name}</td><td>{item.crop}</td><td>{item.area}</td><td>{item.zoneCode}</td><td><Status value={item.status} /></td></tr>)}</tbody></table></div></section>{drawerOpen && profile && <LandDetailDrawer parcel={selectedParcel} profile={profile} onClose={() => setDrawerOpen(false)} />}{showQr && <ActionModal title={`Mã truy xuất ${selectedParcel.id}`} description="Mã QR sẽ liên kết thửa đất với mùa vụ, thu hoạch, đóng gói và lô kho khi bản ghi chuỗi được tạo." onClose={() => setShowQr(false)} onConfirm={() => { setShowQr(false); onNotice(); }} />}{creating && <FormModal title="Thêm thửa đất" description="Bản ghi sẽ được tạo trực tiếp trong MongoDB và dùng ngay cho GIS, sản xuất và truy xuất." fields={fields} onClose={() => setCreating(false)} onSubmit={async (values) => { const [lat, lng] = values.coordinates.split(",").map(Number); try { await apiPost("/api/parcels", { code:values.code, cooperativeCode:"HTX-001", memberCode:values.memberCode, areaHa:Number(values.areaHa), crop:values.crop, zoneCode:values.zoneCode, landType:"Đất nông nghiệp", standard:"conversion", status:"active", geometry:{ type:"Point", coordinates:[lng, lat] } }); setCreating(false); load(); onNotice(); } catch (reason) { setError(reason.message); } }} />}</section>;
}

const parcelMap = (item) => ({ ...item, id:item.code, name:item.memberCode || "Chưa gắn hộ dân", area:`${item.areaHa} ha`, color:item.standard === "VietGAP" ? "#2d7a4f" : "#d99c2b", status:statusText(item.standard || item.status) });
function parcelProfileView({ parcel, member, fieldLogs, documents }) { return { status:statusText(parcel.standard || parcel.status), zoneCode:parcel.zoneCode || "Chưa cập nhật", owner:member ? `${member.code} · ${member.name}` : parcel.memberCode || "Chưa gắn thành viên", landType:parcel.landType || "Chưa cập nhật", coordinates:parcel.geometry?.coordinates ? `${parcel.geometry.coordinates[1]}, ${parcel.geometry.coordinates[0]}` : "Chưa cập nhật", logs:fieldLogs.map((item) => [dateText(item.performedAt), item.material || item.type, statusText(item.status)]), docs:documents.map((item) => [item.code, item.name, dateText(item.expiresAt), statusText(item.status)]) }; }

function landProfile(parcel) { const data = { "TD-042": { status:"Đạt VietGAP", zoneCode:"DT-VT-0362", owner:"TV-102 · Nguyễn Văn Thành", landType:"Đất trồng cây lâu năm", coordinates:"10.0443, 105.7761", logs:[["18/08","Bón phân hữu cơ vi sinh","Đã xác nhận"],["14/08","Kiểm tra sâu bệnh","Đã xác nhận"],["11/08","Tưới nước định kỳ","Đã xác nhận"]], docs:[["HS-DD-042","Giấy tờ quyền sử dụng đất","18/03/2032","Hiệu lực"],["HS-CL-042","Cam kết VietGAP","31/12/2026","Hiệu lực"]] }, "TD-118": { status:"Sắp kiểm tra", zoneCode:"DT-VT-0418", owner:"TV-118 · Trần Thị Lan", landType:"Đất trồng cây lâu năm", coordinates:"10.0488, 105.7841", logs:[["19/08","Thu hoạch đợt 02","Đã xác nhận"],["16/08","Bón phân phục hồi","Đã xác nhận"],["12/08","Khảo sát chất lượng","Chờ xác nhận"]], docs:[["HS-DD-118","Giấy tờ quyền sử dụng đất","20/05/2033","Hiệu lực"],["HS-CL-118","Chứng nhận VietGAP","25/08/2026","Sắp kiểm tra"]] }, "TD-209": { status:"Đang chuyển đổi", zoneCode:"DT-VT-0521", owner:"Tổ liên kết An Phú", landType:"Đất trồng cây lâu năm", coordinates:"10.0389, 105.7862", logs:[["18/08","Bao trái đợt 02","Đã xác nhận"],["15/08","Tưới nước định kỳ","Đã xác nhận"],["13/08","Cập nhật ảnh hiện trạng","Chờ xác nhận"]], docs:[["HS-DD-209","Hồ sơ vùng liên kết","15/10/2031","Hiệu lực"],["HS-CL-209","Kế hoạch chuyển đổi VietGAP","30/09/2026","Đang thực hiện"]] } }; return data[parcel.id] || data["TD-042"]; }

function LandDetailDrawer({ parcel, profile, onClose }) { const [tab, setTab] = useState("Tổng quan"); const tabs = ["Tổng quan","Nhật ký","Hồ sơ pháp lý"]; const table = (columns, rows) => <div className="member-table"><div className="table-scroll"><table><thead><tr>{columns.map((item) => <th key={item}>{item}</th>)}</tr></thead><tbody>{rows.map((row) => <tr key={row[0]}>{row.map((value,index) => <td key={`${row[0]}-${index}`}>{index === row.length - 1 ? <Status value={value} /> : value}</td>)}</tr>)}</tbody></table></div></div>; return <SideSheet title={`${parcel.id} · Hồ sơ thửa đất`} onClose={onClose}><div className="land-drawer"><div className="member-drawer-meta"><div><span>{profile.owner}</span><b>{parcel.crop} · {parcel.area}</b></div><Status value={profile.status} /></div><div className="member-drawer-tabs">{tabs.map((item) => <button key={item} className={tab === item ? "active" : ""} onClick={() => setTab(item)}>{item}</button>)}</div>{tab === "Tổng quan" && <div className="member-drawer-content"><dl className="member-facts"><div><dt>Loại đất</dt><dd>{profile.landType}</dd></div><div><dt>Mã vùng trồng</dt><dd>{profile.zoneCode}</dd></div><div><dt>Tọa độ trung tâm</dt><dd>{profile.coordinates}</dd></div><div><dt>Tiêu chuẩn quản lý</dt><dd>{profile.status}</dd></div></dl><section className="production-progress"><div><span>Mức độ hoàn thiện hồ sơ số</span><b>92% · 11/12 trường dữ liệu</b><small>Cần bổ sung ảnh ranh giới kỳ kiểm tra tới</small></div><i><span style={{ width:"92%" }} /></i></section></div>}{tab === "Nhật ký" && <div className="member-drawer-content">{table(["Ngày","Nội dung","Trạng thái"], profile.logs)}</div>}{tab === "Hồ sơ pháp lý" && <div className="member-drawer-content">{table(["Mã hồ sơ","Tài liệu","Hết hạn","Trạng thái"], profile.docs)}</div>}</div></SideSheet>; }

function CreateForm({ action, onClose, onNotice }) { const fields = forms[action]; if (!fields) return <ActionModal title={action} description="Bản demo sẽ lưu biểu mẫu ở trạng thái nháp. Hệ thống thật sẽ kiểm tra quyền truy cập và dữ liệu bắt buộc trước khi phê duyệt." onClose={onClose} onConfirm={() => { onClose(); onNotice(); }} />; return <FormModal title={action} description="Thông tin có dấu * là bắt buộc. Dữ liệu được lưu dạng nháp trong demo." fields={fields} onClose={onClose} onSubmit={() => { onClose(); onNotice(); }} />; }

function RecordDetail({ columns, row, onClose }) { const [tab, setTab] = useState("Thông tin"); const context = recordContext(row); const tabs = ["Thông tin", "Liên kết", "Kiểm soát & lịch sử"]; return <SideSheet title={`${row[0]} · Hồ sơ vận hành`} onClose={onClose}><div className="member-drawer"><div className="member-drawer-meta"><div><span>{context.type}</span><b>{row[1]}</b></div><Status value={row.at(-1)} /></div><div className="member-drawer-tabs">{tabs.map((item) => <button key={item} className={tab === item ? "active" : ""} onClick={() => setTab(item)}>{item}</button>)}</div>{tab === "Thông tin" && <div className="member-drawer-content"><dl className="member-facts">{columns.map((column, index) => <div key={column}><dt>{column}</dt><dd>{index === columns.length - 1 ? <Status value={row[index]} /> : row[index]}</dd></div>)}</dl></div>}{tab === "Liên kết" && <div className="member-drawer-content"><p className="drawer-copy">Các đầu mối dữ liệu được kiểm tra cùng hồ sơ này để bảo đảm chuỗi vận hành không bị đứt đoạn.</p><dl className="member-facts">{context.links.map(([label,value]) => <div key={label}><dt>{label}</dt><dd>{value}</dd></div>)}</dl></div>}{tab === "Kiểm soát & lịch sử" && <div className="member-drawer-content"><div className="activity-list">{context.history.map(([time,text,state]) => <div key={`${time}-${text}`}><time>{time}</time><p>{text}</p><Status value={state} /></div>)}</div><section className="production-progress"><div><span>Mức hoàn thiện dữ liệu</span><b>{context.completeness}% · đã kiểm tra liên kết</b><small>{context.note}</small></div><i><span style={{ width:`${context.completeness}%` }} /></i></section></div>}<button className="primary-btn full" onClick={onClose}>Đóng hồ sơ</button></div></SideSheet>; }
function recordContext(row) { const code = row[0] || ""; const shared = { links:[["Hợp tác xã quản lý","HTX-001 · HTX Nông nghiệp Tân Thuận"],["Người/bộ phận phụ trách","Điều phối vận hành"],["Hồ sơ & chứng từ","Đã gắn hồ sơ số liên quan"]], history:[["20/08/2026 · 10:15","Cập nhật dữ liệu nghiệp vụ", "Đã xác nhận"],["19/08/2026 · 16:40","Kiểm tra phạm vi truy cập và dữ liệu bắt buộc", "Đã áp dụng"],["18/08/2026 · 09:30","Tạo hồ sơ trong môi trường demo", "Hoàn tất"]], completeness:92, note:"Còn các trường ảnh, tệp gốc hoặc biên bản cần bổ sung theo quy trình thực tế." }; const types = code.startsWith("TS-") ? ["Tài sản HTX",[["Bộ phận quản lý",row[3]],["Lịch bảo trì kế tiếp","28/08/2026"],["Sổ khấu hao","KH-2026 · đang theo dõi"],["Biên bản bàn giao","BBBG-" + code.slice(3)]],"Đối chiếu bảo trì, khấu hao và biên bản bàn giao trước khi chốt kỳ."] : code.startsWith("NK-") ? ["Nhật ký vật tư & canh tác",[["Thửa đất / vùng trồng",row[1]?.split(" · ")[0] || "TD-042"],["Mùa vụ","Thu Đông 2026"],["Hồ sơ vật tư đầu vào","VT-2026-018"],["Thời gian cách ly","Đã kiểm tra theo loại vật tư"]],"Cần có người xác nhận, hồ sơ đầu vào và điều kiện cách ly trước thu hoạch."] : code.startsWith("QR-") ? ["Chuỗi truy xuất nông sản",[["Thửa đất nguồn","TD-042"],["Hộ cung ứng","TV-102 · Nguyễn Văn Thành"],["Mùa vụ & nhật ký","MV-TD-2026 · 12 bản ghi"],["Kho / giao nhận","KHO-01 · Phiếu xuất PXK-118"]],"Chuỗi thửa đất → mùa vụ → thu hoạch → đóng gói → kho được kiểm tra theo mã lô."] : code.startsWith("TV-") ? ["Vốn góp & cổ phần",[["Sổ thành viên điện tử",code],["Kỳ đối soát","Quý III/2026"],["Phương án phân phối","PA-2026-03 · chờ phê duyệt"],["Chứng từ vốn góp","PC-2026-0" + code.slice(-2)]],"Giao dịch vốn và cổ tức chỉ có hiệu lực sau khi hoàn tất phê duyệt."] : code.startsWith("TB-") ? ["Truyền thông nội bộ",[["Phạm vi người nhận",row[2]],["Kênh gửi",row[3]],["Đính kèm","Có hồ sơ thông báo"],["Lịch hoạt động liên quan","Lịch điều hành tuần 34"]],"Theo dõi xác nhận đọc và lưu vết gửi thông báo theo từng nhóm nhận."] : ["Hồ sơ vận hành",shared.links,shared.note]; return { type:types[0], links:types[1] || shared.links, history:shared.history, completeness:code.startsWith("QR-") ? 96 : code.startsWith("NK-") ? 88 : shared.completeness, note:types[2] || shared.note }; }
function GisModule({ parcel, onSelectParcel, onNotice }) { const [showQr, setShowQr] = useState(false); const [creatingParcel, setCreatingParcel] = useState(false); const [journalOpen, setJournalOpen] = useState(false); const parcelFields = [{ name:"parcelCode", label:"Mã thửa đất", value:"TD-210", required:true },{ name:"owner", label:"Chủ sử dụng", placeholder:"Chọn hoặc nhập thành viên", required:true },{ name:"area", label:"Diện tích (ha)", type:"number", placeholder:"0,0", required:true },{ name:"landType", label:"Loại đất", type:"select", options:["Đất trồng cây lâu năm","Đất trồng cây hàng năm","Đất nông nghiệp khác"], required:true },{ name:"crop", label:"Cây trồng chính", type:"select", options:["Sầu riêng Ri6","Xoài cát Hòa Lộc","Bưởi da xanh","Chanh không hạt"], required:true },{ name:"purpose", label:"Mục đích sử dụng", type:"select", options:["Vùng sản xuất liên kết","Vùng đạt VietGAP","Vùng đang chuyển đổi"], required:true },{ name:"coordinates", label:"Tọa độ vị trí", value:"10.043000, 105.781000", wide:true, required:true }]; return <section className="module-screen"><ModuleHero icon={IconMap2} eyebrow="Quản lý đất đai" title="Vùng sản xuất & GIS" description="Tra cứu thửa đất theo hộ dân, cây trồng, tiêu chuẩn và mùa vụ." actionLabel="Quản lý thửa đất" onAction={() => setCreatingParcel(true)} /><div className="gis-workspace panel"><div className="full-map"><MapWidget selectedParcel={parcel} onSelect={onSelectParcel} /><div className="map-actions"><button className="outline-btn" onClick={() => setCreatingParcel(true)}>Thêm thửa đất</button><button className="primary-btn" onClick={() => setShowQr(true)}><IconQrcode size={16} />Tạo mã truy xuất</button></div><div className="map-count"><IconMap2 size={17} /><b>46 thửa đất</b><span>412,6 ha đã số hóa</span></div><div className="map-context"><b>Địa danh trên bản đồ thật</b><span>Đường Đinh Tiên Hoàng, phường Ninh Kiều, TP Cần Thơ</span><small>Dữ liệu nền: OpenStreetMap · Vùng TD-042 là dữ liệu mô phỏng</small></div></div><aside className="gis-detail"><span className="small-label">HỒ SƠ THỬA ĐẤT</span><h3>{parcel.id}</h3><div className="status ok">Đạt chuẩn VietGAP</div><Detail label="Chủ sử dụng" value={parcel.name} /><Detail label="Cây trồng" value={parcel.crop} /><Detail label="Diện tích" value={parcel.area} /><Detail label="Mã vùng trồng" value="DT-VT-0362" /><Detail label="Nhật ký kỳ này" value="12 bản ghi" /><button className="outline-btn wide" onClick={() => setJournalOpen(true)}><IconFileText size={17} />Xem nhật ký canh tác</button></aside></div><div className="gis-summary"><Summary icon={IconCircleCheck} value="358,2 ha" label="Đạt VietGAP" /><Summary icon={IconCalendarEvent} value="32,4 ha" label="Đến kỳ kiểm tra" /><Summary icon={IconPlant2} value="21,8 ha" label="Đang chuyển đổi" /></div>{journalOpen && <ActionModal title={`Nhật ký canh tác ${parcel.id}`} description={`12 bản ghi mẫu cho ${parcel.crop}: bón phân hữu cơ ngày 18/08, kiểm tra sâu bệnh ngày 14/08 và tưới nước định kỳ ngày 11/08.`} onClose={() => setJournalOpen(false)} onConfirm={() => { setJournalOpen(false); onNotice(); }} />}{showQr && <ActionModal title={`Mã truy xuất ${parcel.id}`} description="Mã QR sẽ liên kết thửa đất, mùa vụ Thu Đông 2026 và lô đóng gói khi tạo phiếu thu hoạch." onClose={() => setShowQr(false)} onConfirm={() => { setShowQr(false); onNotice(); }} />}{creatingParcel && <FormModal title="Thêm thửa đất" description="Khai báo thửa đất phục vụ quản lý vùng sản xuất, nhật ký canh tác và truy xuất nguồn gốc." fields={parcelFields} onClose={() => setCreatingParcel(false)} onSubmit={() => { setCreatingParcel(false); onNotice(); }} />}</section>; }
function Detail({ label, value }) { return <div className="detail-row"><span>{label}</span><b>{value}</b></div>; }
function Summary({ icon: Icon, value, label }) { return <div><Icon /><p><b>{value}</b><span>{label}</span></p></div>; }
